import re

def parse_music(music_string: str) -> List[int]:
    notes = re.findall(r'(\.|\s+) ([\s\S]*?) \.', music_string.lower())
    durations = {r'(\+|\|-|\|\|) (\d+)' : 0}

    for note, duration in notes:
        beat = int(re.match(r'(\+|\|-|\|\|) (\d+)', duration).group(2))
        if duration not in durations:
            durations[duration] = beat
        else:
            durations[duration] += beat

    parsed_durations = []
    for duration, beat in durations.items():
        parsed_durations.append(beat)

    return parsed_durations
