    if not sorted_lst:
        return -1  # No non-zero numbers in the sorted list

    frequency_dict = {}
    for number in sorted_lst:
        if number > 0:  # Update frequency dictionary to count numbers greater than zero
            if number in frequency_dict:
                frequency_dict[number] += 1
            else:
                frequency_dict[number] = 1

    greatest_number_greater_zero = None
    greatest_frequency = -1
    greatest_prime = -1

    for number, frequency in frequency_dict.items():
        if number > 0 and frequency >= number:
            if greatest_number_greater_zero is None or greatest_frequency < frequency:
                greatest_number_greater_zero = number
                greatest_frequency = frequency

    if greatest_number_greater_zero is not None and greatest_number_greater_zero > 0:
        if greatest_number_greater_zero > greatest_prime:
            greatest_prime = greatest_number_greater_zero

    return greatest_prime if greatest_prime > 0 else -1  # Check if the current greatest value greater zero exists
