def total_match(lst1, lst2):
    '''
    Write a function that accepts two lists of strings and returns the list that has total number of chars in the all strings of the list less than the other list.

    if the two lists have the same number of chars, return the first list.

    Examples
    total_match([], []) ➞ []
    total_match(['hi', 'admin'], ['hI', 'Hi']) ➞ ['hI', 'Hi']
    total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project']) ➞ ['hi', 'admin']
    total_match(['hi', 'admin'], ['hI', 'hi', 'hi']) ➞ ['hI', 'hi', 'hi']
    total_match(['4'], ['1', '2', '3', '4', '5']) ➞ ['4']
    '''
    set1 = set(lst1)
    set2 = set(lst2)

    if len(set1) > len(set2):
        return min(set(lst1), set(lst2))
    elif len(set1) < len(set2):
        return min(set(lst2), set(lst1))
    else:
        return sorted(set(lst1), key=len) if sorted(lst1, key=len) != lst2 else sorted(set(lst2), key=len)
