    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    # Check if the number is less than 100 and is a prime number
    if a < 100:
        if is_prime(a):
            prime_factors = []
            i = 2
            while i * i <= a:
                if a % i:
                    i += 1
                else:
                    a //= i
                    prime_factors.append(i)
            return len(prime_factors) == 3 and sum(prime_factors) == a
        else:
            return False
    return False

