    """
    Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers
    """
    # Check if n is less than or equal to 0 or if n is divisible by 4
    if n <= 0 or n % 4 == 0:
        return False

    # If odd number, check for the following conditions:
    if n % 2 != 0:
        return True

    # Iterate over all possible combinations of 4 positive even numbers
    for i in range(1, n//2 + 1):
        for j in range(1, n//2 + 1):
            if i + j + n - 2*j == n:
                return True
    return False

