def specialFilter(nums):
    """
    This function takes an array of numbers as input and returns the number of elements
    in the array that are greater than 10 and both first and last digits of a number 
    are odd (1, 3, 5, 7, 9).

    For example:
    specialFilter([15, -73, 14, -15]) => 1
    specialFilter([33, -2, -3, 45, 21, 109]) => 2
    """
    def isFirstDigitOdd(n):
        return len(str(n)) % 2 == 1

    def isLastDigitOdd(n):
        return n % 10 % 2 == 1

    even_digit_filter = [n for n in nums if isFirstDigitOdd(n) and isLastDigitOdd(n)]

    if len(even_digit_filter) == 0:
        return 0
    else:
        return len(even_digit_filter)

