    # Check if the inputs are valid planet names
    if not (type(planet1) in [str, int] and 
            type(planet2) in [str, int]):
        return ()
    elif planet1 == "Uranus" or planet2 == "Uranus":
        return ()
    elif planet1 == "Earth" or planet2 == "Earth":
        return ()
    elif planet1 == "Mars" or planet2 == "Mars":
        return ()
    elif planet1 in ("Neptune", "Neptune", "Terrestrial") or (
        planet2 in ("Neptune", "Neptune", "Terrestrial") and
        planet1 != "Venus" and planet1 != "Earth" and planet2 != "Venus") or:
        return ()
    else:
        # Get the orbits of the two planets
        orbits = {
            'Mercury': {'Jupiter', 'Saturn', 'Uranus'},
            'Venus': {'Earth', 'Mars'},
            'Earth': {'Mercury', 'Venus', 'Mars', 'Jupiter', 'Saturn'},
            'Mars': {'Venus', 'Earth', 'Jupiter', 'Saturn', 'Uranus'},
            'Jupiter': {'Saturn', 'Uranus', 'Neptune'},
            'Saturn': {'Uranus', 'Neptune'},
            'Uranus': {'Earth', 'Mars', 'Jupiter', 'Saturn'}
        }

        # Find the planet positions between the first and second planet
        positions = np.where(orbits[planet1] <= orbits[planet2])[0]
        if len(positions) < 1:
            return ()
        elif len(positions) == 1:
            return orbits[planet1][positions[0]] + orbits[planet2][positions[0]]
        else:
            # Return the list of planets within the specified range, sorted by distance
            return [orbits[planet1][i] + orbits[planet2][positions[i]] for i in range(len(positions))]

